CREATE TABLE IF NOT EXISTS dinero_vat_role_reviews (
  mapping_id INTEGER PRIMARY KEY REFERENCES account_role_mappings(id),
  company_cvr TEXT NOT NULL,
  chart_path TEXT NOT NULL,
  chart_sha256 TEXT NOT NULL CHECK(length(chart_sha256) = 64),
  inventory_sha256 TEXT NOT NULL CHECK(length(inventory_sha256) = 64),
  source_account_name TEXT NOT NULL,
  previous_dedicated_reverse_charge_account TEXT,
  last_existing_entry_id INTEGER NOT NULL CHECK(last_existing_entry_id >= 0)
);
CREATE TRIGGER IF NOT EXISTS dinero_vat_role_reviews_no_update BEFORE UPDATE ON dinero_vat_role_reviews BEGIN SELECT RAISE(ABORT, 'Dinero VAT role evidence is immutable'); END;
CREATE TRIGGER IF NOT EXISTS dinero_vat_role_reviews_no_delete BEFORE DELETE ON dinero_vat_role_reviews BEGIN SELECT RAISE(ABORT, 'Dinero VAT role evidence is append-only'); END;
